// Hand-written Go service with chi (never generated by gherkin-ai).
package httpapi

import (
	"net/http"

	"github.com/go-chi/chi/v5"
)

func NewRouter(h *OrderHandler) http.Handler {
	r := chi.NewRouter()
	r.Get("/health", health)
	r.Route("/orders", func(r chi.Router) {
		r.Use(RequireAuth)
		r.Post("/", h.PlaceOrder)
		r.Post("/{id}/cancel", h.CancelOrder)
	})
	mux := http.NewServeMux()
	mux.HandleFunc("POST /shipments/{id}/dispatch", h.DispatchShipment)
	mux.Handle("/", r)
	return mux
}
